    },
    {
      "statement": "Für Barrierefreiheit sollen große Schriftgrößen verwendet werden.",
      "type": "requirement",
      "sourceUnitIds": [
        "AU-0133"
      ],
      "derivation": "explicit",
      "uncertainty": "none"
    },
    {
      "statement": "Für Barrierefreiheit soll ausreichender Kontrast verwendet werden.",
      "type": "requirement",
      "sourceUnitIds": [
        "AU-0133"
      ],
      "derivation": "explicit",
      "uncertainty": "none"
    },
    {
      "statement": "Für Barrierefreiheit sollen nicht zu viele Farben verwendet werden.",
      "type": "requirement",
      "sourceUnitIds": [
        "AU-0133"
      ],
      "derivation": "explicit",
      "uncertainty": "none"
    },
    {
      "statement": "Sprachbefehle oder alternative Eingabemethoden für beeinträchtigte Nutzer sollen berücksichtigt werden.",
      "type": "requirement",
      "sourceUnitIds": [
        "AU-0134"
      ],
      "derivation": "explicit",
      "uncertainty": "uncertain"
    },
    {
      "statement": "Animationen sollen nicht eingebaut werden.",
