      "derivation": "explicit",
      "uncertainty": "none"
    },
    {
      "statement": "Falls Animationen oder Feedback eingesetzt werden, sollen sie nicht ablenkend sein.",
      "type": "requirement",
      "sourceUnitIds": [
        "AU-0135"
      ],
      "derivation": "explicit",
      "uncertainty": "uncertain"
    },
    {
      "statement": "Das Design der App soll zugänglich und intuitiv sein.",
      "type": "requirement",
      "sourceUnitIds": [
        "AU-0136"
      ],
      "derivation": "explicit",
      "uncertainty": "none"
    },
    {
      "statement": "Das Design der App soll klares Branding aufweisen.",
      "type": "requirement",
      "sourceUnitIds": [
        "AU-0136"
      ],
      "derivation": "explicit",
      "uncertainty": "none"
    },
    {
      "statement": "Das Design der App soll ausreichende Hilfe-Funktionen enthalten.",
      "type": "requirement",
      "sourceUnitIds": [
        "AU-0136"
      ],
      "derivation": "explicit",
      "uncertainty": "none"
    },
    {
      "statement": "Das Design der App soll einen starken Fokus auf Benutzerfreundlichkeit haben.",
      "type": "requirement",
      "sourceUnitIds": [
