              "derivation": "explicit",
              "uncertainty": "none"
            },
            {
              "statement": "Die App soll einen Kommunikationsscreen enthalten.",
              "type": "requirement",
              "sourceUnitIds": [
                "AU-0025"
              ],
              "derivation": "explicit",
              "uncertainty": "none"
            },
            {
              "statement": "Der Kommunikationsscreen soll in verbale und nonverbale Kommunikation unterteilt werden.",
              "type": "requirement",
              "sourceUnitIds": [
                "AU-0025"
              ],
              "derivation": "explicit",
              "uncertainty": "none"
            },
            {
              "statement": "Im Kommunikationsbereich sollen Daten zum Verständnis verschiedener Kommunikationsweisen gespeichert und jederzeit abrufbar sein.",
              "type": "requirement",
              "sourceUnitIds": [
                "AU-0025"
              ],
              "derivation": "explicit",
              "uncertainty": "none"
            },
            {
              "statement": "Die App soll eventuell eine Seite für Medikamentenvergabe und Terminkalender enthalten.",
