                "AU-0026"
              ],
              "derivation": "explicit",
              "uncertainty": "none"
            },
            {
              "statement": "Neue Erfahrungen müssen auf der Kommunikationsseite hinzugefügt werden können.",
              "type": "requirement",
              "sourceUnitIds": [
                "AU-0026"
              ],
              "derivation": "explicit",
              "uncertainty": "none"
