              "sourceUnitIds": [
                "AU-0031",
                "AU-0033"
              ],
              "derivation": "explicit",
              "uncertainty": "none"
            },
            {
              "statement": "Die Videofunktion soll besonders neuen Betreuern helfen.",
              "type": "requirement",
              "sourceUnitIds": [
